using Grpc.Core;
using MediatR;
using Microsoft.AspNetCore.Hosting;
using Microsoft.EntityFrameworkCore;
using Modules.Products.Contracts;
using Modules.Products.Entities;
using Modules.Products.Interfaces;
using Modules.Products.Persistence;
using Shared.Events;
// IMPORTANT: Use the namespace generated by your protobuf file
using Modules.Orders.Integration.Protos;
using Microsoft.Extensions.Logging;

namespace Modules.Products.Services;

public class ProductService : IProductService
{
    private readonly ProductsDbContext _context;
    private readonly IWebHostEnvironment _env;
    private readonly IMediator _mediator;
    private readonly InventoryService.InventoryServiceClient _inventoryClient;

    // Inject the gRPC client
    public ProductService(
        ProductsDbContext context, 
        IWebHostEnvironment env, 
        IMediator mediator,
        InventoryService.InventoryServiceClient inventoryClient)
    {
        _context = context;
        _env = env;
        _mediator = mediator;
        _inventoryClient = inventoryClient;
    }

    public async Task<ProductResponse> CreateProductAsync(CreateProductRequest request)
    {
        string imageUrl = string.Empty;
        if (request.Image != null && request.Image.Length > 0)
        {
            var webRoot = _env.WebRootPath ?? Path.Combine(Directory.GetCurrentDirectory(), "wwwroot");
            var uploadsFolder = Path.Combine(webRoot, "images");
            Directory.CreateDirectory(uploadsFolder);
            var uniqueFileName = $"{Guid.NewGuid()}_{request.Image.FileName}";
            var filePath = Path.Combine(uploadsFolder, uniqueFileName);
            using var fileStream = new FileStream(filePath, FileMode.Create);
            await request.Image.CopyToAsync(fileStream);
            imageUrl = $"/images/{uniqueFileName}";
        }

        var product = new Product
        {
            Name = request.Name,
            Description = request.Description,
            Price = request.Price,
            Category = request.Category,
            CreatedAt = DateTime.UtcNow,
            ImageUrl = imageUrl
        };

        // 1. Commit to Local Database
        _context.Products.Add(product);
        await _context.SaveChangesAsync();

        // 2. Synchronous gRPC call to Node.js Vault with a 2-second timeout
        var callOptions = new CallOptions().WithDeadline(DateTime.UtcNow.AddMilliseconds(2000));
        
        try
        {
            var initRequest = new InitializeRequest 
            { 
                ProductId = product.Id.ToString(), 
                InitialQuantity = request.AvailableQuantity // Passed from Postman
            };
            
            var initResponse = await _inventoryClient.InitializeStockAsync(initRequest, callOptions);
            
            if (!initResponse.Success)
            {
                // SAGA ROLLBACK: If Node.js rejects the insertion, remove the product locally
                _context.Products.Remove(product);
                await _context.SaveChangesAsync();
                throw new Exception($"Failed to initialize inventory: {initResponse.Message}");
            }
        }
        catch (RpcException ex)
        {
            // SAGA ROLLBACK: If Node.js is offline or times out, remove the product locally
            _context.Products.Remove(product);
            await _context.SaveChangesAsync();
            throw new Exception($"Inventory service unavailable. Product creation aborted. Status: {ex.Status.StatusCode}");
        }

        // 3. Broadcast the event to trigger the Notifications module
        await _mediator.Publish(new ProductCreatedIntegrationEvent(product.Id, product.Name, product.Category, product.Price));

        return MapToResponse(product, request.AvailableQuantity);
    }

    public async Task<ProductResponse?> GetProductAsync(Guid id)
    {
        var product = await _context.Products.FindAsync(id);
        if (product == null) return null;

        int availableQuantity = await FetchQuantityFromInventoryAsync(id);
        return MapToResponse(product, availableQuantity);
    }
public async Task<PaginatedProductResponse> GetProductsAsync(string? category, int page, int pageSize)
    {
        var query = _context.Products.AsQueryable();
        if (!string.IsNullOrWhiteSpace(category))
        {
            query = query.Where(p => p.Category.ToLower() == category.ToLower());
        }

        var totalItems = await query.CountAsync();
        var products = await query.Skip((page - 1) * pageSize).Take(pageSize).ToListAsync();
        
        var productResponses = new List<ProductResponse>();
        
        // Fetch quantities for the current page of products
        foreach (var product in products)
        {
            int qty = await FetchQuantityFromInventoryAsync(product.Id);
            productResponses.Add(MapToResponse(product, qty));
        }

        return new PaginatedProductResponse(
            totalItems, page, pageSize, 
            (int)Math.Ceiling(totalItems / (double)pageSize), 
            productResponses
        );
    }

    // Helper method to keep your code clean
    private async Task<int> FetchQuantityFromInventoryAsync(Guid productId)
    {
        try
        {
            var request = new CheckQuantityRequest { ProductId = productId.ToString() };
            // Optional: Add a short deadline so the catalog doesn't hang if inventory is down
            var callOptions = new CallOptions().WithDeadline(DateTime.UtcNow.AddMilliseconds(1000));
            
            var response = await _inventoryClient.CheckQuantityAsync(request, callOptions);

            return response.AvailableQuantity;
        }
        catch (RpcException)
        {
            // If the inventory service is down, fallback to 0 or handle accordingly
            return 0; 
        }
    }
    private static ProductResponse MapToResponse(Product product, int quantity) => 
        new(product.Id, product.Name, product.Description, product.Price, product.Category, quantity, product.ImageUrl, product.CreatedAt);
}